"""C1: docs/I18N-REVIEW.md is generated by i18n/review_table.py from the catalogs plus a hand-written flag list."""
from __future__ import annotations

import pathlib

import pytest

from i18n import review_table as rt
from test_i18n_completeness import KNOWN_INCONSISTENCIES


def test_the_review_file_is_up_to_date():
    assert rt.main(["--check"]) == 0, "run: cd server && ../.venv/bin/python -m i18n.review_table"


def test_check_detects_drift_and_a_missing_file(tmp_path: pathlib.Path):
    out = tmp_path / "REVIEW.md"
    assert rt.main(["--check"], out) == 1  # missing
    assert rt.main([], out) == 0 and rt.main(["--check"], out) == 0
    out.write_text(out.read_text(encoding="utf-8").replace("| Key |", "| Clé |"), encoding="utf-8")
    assert rt.main(["--check"], out) == 1
    assert rt.main([], out) == 0 and rt.main(["--check"], out) == 0  # regenerating repairs it


def test_every_flag_resolves_and_has_a_reason():
    seen = set()
    for kind, ref, source, why in rt.FLAGS:
        assert kind in rt.KINDS and why.strip() and source.strip(), (kind, ref)
        assert (kind, ref) not in seen, (kind, ref)
        seen.add((kind, ref))
        en, bg = rt.lookup(kind, ref)  # KeyError = the flagged entry no longer exists: unflag it
        assert en.strip() and bg.strip(), (kind, ref)
    assert len(rt.FLAGS) >= 60


def test_every_flagged_name_has_a_transliteration_and_vice_versa():
    names = {ref for kind, ref, _s, _w in rt.FLAGS if kind == "name"}
    assert names == set(rt.TRANSLITERATION)


def test_the_pinned_wording_inconsistencies_are_in_the_review_table():
    """Every real inconsistency pinned by test_i18n_completeness.py is reviewable (false positives are not)."""
    flagged_copy = {ref for kind, ref, _s, _w in rt.FLAGS if kind == "copy"}
    flagged_export = {ref for kind, ref, _s, _w in rt.FLAGS if kind == "export"}
    for key, reason in KNOWN_INCONSISTENCIES.items():
        surface, _term, path = key.split(":", 2)
        if reason.startswith(("false positive", "Bulgarian UI page")):
            continue  # the legacy English page words are represented by the nav.steps / sentence rows
        assert path in (flagged_export if surface == "export" else flagged_copy), key


def test_rows_render_in_the_document():
    text = pathlib.Path(rt.OUT).read_text(encoding="utf-8")
    assert f"{len(rt.FLAGS)} rows." in text
    for kind, ref, _s, _w in rt.FLAGS:
        assert f"`{kind}:{ref}`" in text
